-- Create "passkey_accounts" table
CREATE TABLE "passkey_accounts" ("user_id" uuid NOT NULL, "user_handle" bytea NOT NULL, PRIMARY KEY ("user_id"), CONSTRAINT "passkey_accounts_user_handle_key" UNIQUE ("user_handle"), CONSTRAINT "passkey_accounts_user_id_user_handle_key" UNIQUE ("user_id", "user_handle"), CONSTRAINT "passkey_accounts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_account_handle_length" CHECK (octet_length(user_handle) = 32));
-- Create "passkey_credentials" table
CREATE TABLE "passkey_credentials" ("id" bytea NOT NULL, "user_id" uuid NOT NULL, "user_handle" bytea NOT NULL, "public_key_cose" bytea NOT NULL, "sign_count" bigint NOT NULL, "backup_eligible" boolean NOT NULL, "is_backed_up" boolean NOT NULL, "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(), "last_used_at" timestamptz NULL, "revoked_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "passkey_credentials_user_id_id_key" UNIQUE ("user_id", "id"), CONSTRAINT "passkey_credential_owner_fk" FOREIGN KEY ("user_id", "user_handle") REFERENCES "passkey_accounts" ("user_id", "user_handle") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_backup_flags" CHECK ((NOT is_backed_up) OR backup_eligible), CONSTRAINT "passkey_counter_range" CHECK ((sign_count >= 0) AND (sign_count <= '4294967295'::bigint)), CONSTRAINT "passkey_credential_id_length" CHECK ((octet_length(id) >= 1) AND (octet_length(id) <= 1023)), CONSTRAINT "passkey_credential_times" CHECK (isfinite(created_at) AND ((last_used_at IS NULL) OR isfinite(last_used_at)) AND ((revoked_at IS NULL) OR isfinite(revoked_at))), CONSTRAINT "passkey_key_length" CHECK ((octet_length(public_key_cose) >= 1) AND (octet_length(public_key_cose) <= 512)));
-- Create "auth_sessions" table
CREATE TABLE "auth_sessions" ("token_hash" bytea NOT NULL, "user_id" uuid NOT NULL, "credential_id" bytea NOT NULL, "origin" text NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz NULL, PRIMARY KEY ("token_hash"), CONSTRAINT "auth_session_credential_owner_fk" FOREIGN KEY ("user_id", "credential_id") REFERENCES "passkey_credentials" ("user_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "auth_session_expiry" CHECK (isfinite(created_at) AND isfinite(expires_at) AND (expires_at > created_at) AND (expires_at <= (created_at + '1 day'::interval))), CONSTRAINT "auth_session_hash_length" CHECK (octet_length(token_hash) = 32), CONSTRAINT "auth_session_origin" CHECK (origin = ANY (ARRAY['http://localhost:5173'::text, 'http://localhost:5174'::text])), CONSTRAINT "auth_session_revocation" CHECK ((revoked_at IS NULL) OR (isfinite(revoked_at) AND (revoked_at >= created_at))));
-- Create index "auth_sessions_expiry_idx" to table: "auth_sessions"
CREATE INDEX "auth_sessions_expiry_idx" ON "auth_sessions" ("expires_at");
-- Create index "auth_sessions_user_idx" to table: "auth_sessions"
CREATE INDEX "auth_sessions_user_idx" ON "auth_sessions" ("user_id");
-- Create "passkey_registration_intents" table
CREATE TABLE "passkey_registration_intents" ("challenge_id" uuid NOT NULL, "user_id" uuid NOT NULL, "user_handle" bytea NOT NULL, PRIMARY KEY ("challenge_id"), CONSTRAINT "passkey_registration_intents_user_handle_key" UNIQUE ("user_handle"), CONSTRAINT "passkey_registration_intents_user_id_key" UNIQUE ("user_id"), CONSTRAINT "passkey_registration_intents_challenge_id_fkey" FOREIGN KEY ("challenge_id") REFERENCES "webauthn_challenges" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_intent_handle_length" CHECK (octet_length(user_handle) = 32));
